import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';

@Component({
  selector: 'app-memoization-demo',
  template: ''
})
export class MemoizationDemoComponent implements OnInit {
  regularResult: number = 0;
  memoizedResult: number = 0;
  cache: { [key: number]: number } = {};

  ngOnInit() {
    // Initialization logic will go here
  }

  expensiveCalculation(n: number): number {
    // Simulate expensive calculation
    let result = 0;
    for (let i = 0; i < n * 1000000; i++) {
      result += Math.random();
    }
    return result;
  }

  calculateRegular() {
    const input = 5;
    this.regularResult = this.expensiveCalculation(input);
  }

  calculateMemoized() {
    const input = 5;
    if (this.cache[input]) {
      this.memoizedResult = this.cache[input];
    } else {
      const result = this.expensiveCalculation(input);
      this.cache[input] = result;
      this.memoizedResult = result;
    }
  }
}
